class TransformerBlock(nn.Module):
    def __init__(self, d_model, n_heads):
        super().__init__()
        self.ln1  = nn.LayerNorm(d_model)
        self.attn = MultiHeadSelfAttention(d_model, n_heads, causal=True)
        self.ln2  = nn.LayerNorm(d_model)
        self.ffn  = nn.Sequential(
            nn.Linear(d_model, 4 * d_model), nn.GELU(),
            nn.Linear(4 * d_model, d_model),
        )

    def forward(self, x):
        x = x + self.attn(self.ln1(x))     # residual 1: attention MOVES information
        x = x + self.ffn(self.ln2(x))      # residual 2: the FFN TRANSFORMS it
        return x


class MiniTransformer(nn.Module):
    def __init__(self, vocab, d_model=64, n_heads=1, n_layers=1, max_len=64,
                 use_pe=True):
        super().__init__()
        self.use_pe = use_pe
        self.emb    = nn.Embedding(vocab, d_model)
        self.register_buffer("pe", sinusoidal_pe(max_len, d_model))
        self.blocks = nn.ModuleList([TransformerBlock(d_model, n_heads)
                                     for _ in range(n_layers)])
        self.ln_f   = nn.LayerNorm(d_model)
        self.head   = nn.Linear(d_model, vocab)

    def forward(self, idx):
        x = self.emb(idx)
        if self.use_pe:
            x = x + self.pe[:idx.shape[1]]
        for b in self.blocks:
            x = b(x)
        return self.head(self.ln_f(x))

model = MiniTransformer(vocab=11)
print(model)
print("\nparameters:", sum(p.numel() for p in model.parameters()))

